<?php
declare(strict_types=1);
require dirname(__DIR__).'/v10-lib.php';$u=require_login();$cid=(int)$u['company_id'];$pdo=db();$method=$_SERVER['REQUEST_METHOD']??'GET';if($method!=='GET')verify_csrf();require_cap_v10($method==='GET'?'sales.read':'sales.write');$action=(string)($_GET['action']??'list');
try{switch($action){case'list':$st=$pdo->prepare('SELECT * FROM v10_web_forms WHERE company_id=? ORDER BY updated_at DESC');$st->execute([$cid]);$items=$st->fetchAll();foreach($items as &$x)$x['fields']=v10_json_decode((string)$x['fields_json']);json_response(['ok'=>true,'items'=>$items]);case'save':$b=body_json();$id=(int)req($b,'id',0);$name=trim((string)req($b,'name',''));if(!$name)json_response(['ok'=>false,'error'=>'name_required'],422);$fields=(array)req($b,'fields',['name','phone','email','message']);$key=(string)req($b,'public_key','');if(!$key)$key=v10_generate_token(18);$vals=[$name,$key,req($b,'title_fa',$name),req($b,'title_en',$name),json_encode($fields,JSON_UNESCAPED_UNICODE),!empty($b['active'])?1:0];if($id)$pdo->prepare('UPDATE v10_web_forms SET name=?,public_key=?,title_fa=?,title_en=?,fields_json=?,active=? WHERE id=? AND company_id=?')->execute([...$vals,$id,$cid]);else{$pdo->prepare('INSERT INTO v10_web_forms(company_id,name,public_key,title_fa,title_en,fields_json,active,created_by) VALUES(?,?,?,?,?,?,?,?)')->execute([$cid,...$vals,$u['id']]);$id=(int)$pdo->lastInsertId();}$embed='<iframe src="'.rtrim((string)envv('APP_URL',''),'/').'/web-lead.php?k='.rawurlencode($key).'" style="width:100%;min-height:520px;border:0"></iframe>';json_response(['ok'=>true,'id'=>$id,'public_key'=>$key,'embed'=>$embed]);case'delete':$b=body_json();$pdo->prepare('DELETE FROM v10_web_forms WHERE id=? AND company_id=?')->execute([(int)req($b,'id',0),$cid]);json_response(['ok'=>true]);default:json_response(['ok'=>false,'error'=>'unknown_action'],404);}}catch(Throwable $e){error_log($e->__toString());json_response(['ok'=>false,'error'=>'server_error','message'=>envv('APP_ENV','local')==='local'?$e->getMessage():'Internal server error'],500);}
